using System;using System.IO;using System.IO.Pipes;using System.Diagnostics;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Runtime.InteropServices;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
namespace SpatialWallpaper.Sdk.Hosting {
 // Trusted client IPC only. Both endpoints pin the original process identity;
 // the secret is scoped to one companion and never enters author content.
 public sealed class ContentSurfaceConnection:IDisposable {
  readonly string pipe,auth;readonly PinnedProcessOwner owner;readonly SemaphoreSlim lane=new SemaphoreSlim(1,1);bool disposed;
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetNamedPipeServerProcessId(Microsoft.Win32.SafeHandles.SafePipeHandle pipe,out uint pid);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetNamedPipeClientProcessId(Microsoft.Win32.SafeHandles.SafePipeHandle pipe,out uint pid);
  public ContentSurfaceConnection(string pipe,string auth,int pid,long creation){ValidateEndpoint(pipe,auth);this.pipe=pipe;this.auth=auth;owner=PinnedProcessOwner.Open(pid,creation);}
  public static void ValidateEndpoint(string pipe,string auth){if(pipe==null||!pipe.StartsWith("SpatialWallpaper.ContentSurface.",StringComparison.Ordinal)||pipe.Length!=64||!Guid.TryParseExact(pipe.Substring(32),"N",out var id)||id==Guid.Empty||auth==null||auth.Length!=64||auth.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f')))throw new InvalidDataException("content-surface-endpoint");}
  public static void RequireClient(NamedPipeServerStream stream,PinnedProcessOwner expected){if(expected.HasExited||!GetNamedPipeClientProcessId(stream.SafePipeHandle,out var pid)||pid!=expected.Id)throw new InvalidDataException("content-surface-client-identity");}
  static void Wait(Task task,Stopwatch clock,int deadline){int left=deadline-(int)clock.ElapsedMilliseconds;if(left<=0||!task.Wait(left)){_ = task.ContinueWith(done=>{var observed=done.Exception;},TaskContinuationOptions.OnlyOnFaulted);throw new TimeoutException("content-surface-io-deadline");}task.GetAwaiter().GetResult();}
  static void Read(Stream stream,byte[] bytes,Stopwatch clock,int deadline){int at=0;while(at<bytes.Length){var pending=stream.ReadAsync(bytes,at,bytes.Length-at);Wait(pending,clock,deadline);int count=pending.GetAwaiter().GetResult();if(count<=0)throw new EndOfStreamException();at+=count;}}
  public static JObject ReadPacket(Stream stream,int deadline=45000){var clock=Stopwatch.StartNew();var size=new byte[4];Read(stream,size,clock,deadline);int length=BitConverter.ToInt32(size,0);if(length<1||length>32768)throw new InvalidDataException("content-surface-packet-size");var bytes=new byte[length];Read(stream,bytes,clock,deadline);using(var text=new StringReader(new UTF8Encoding(false,true).GetString(bytes)))using(var reader=new JsonTextReader(text){MaxDepth=12,DateParseHandling=DateParseHandling.None}){var result=JObject.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(reader.Read())throw new InvalidDataException("content-surface-packet-tail");return result;}}
  public static void WritePacket(Stream stream,JObject value,int deadline=5000){var bytes=Encoding.UTF8.GetBytes(value.ToString(Formatting.None));if(bytes.Length<1||bytes.Length>32768)throw new InvalidDataException("content-surface-packet-size");var clock=Stopwatch.StartNew();Wait(stream.WriteAsync(BitConverter.GetBytes(bytes.Length),0,4),clock,deadline);Wait(stream.WriteAsync(bytes,0,bytes.Length),clock,deadline);}
  public async Task<JObject> CallAsync(string operation,JObject payload){await lane.WaitAsync().ConfigureAwait(false);try{if(disposed||owner.HasExited)throw new InvalidOperationException("content-surface-owner-ended");return await Task.Run(()=>{using(var stream=new NamedPipeClientStream(".",pipe,PipeDirection.InOut,PipeOptions.Asynchronous)){stream.Connect(2000);if(!GetNamedPipeServerProcessId(stream.SafePipeHandle,out var pid)||pid!=owner.Id||owner.HasExited)throw new InvalidDataException("content-surface-server-identity");string request=Guid.NewGuid().ToString("N");WritePacket(stream,new JObject{{"request",request},{"auth",auth},{"operation",operation},{"payload",payload}});var reply=ReadPacket(stream);TrustedRuntimeDistribution.Fields(reply,"request","ok","result","error");if(reply["request"]?.Type!=JTokenType.String||(string)reply["request"]!=request||reply["ok"]?.Type!=JTokenType.Boolean)throw new InvalidDataException("content-surface-reply-identity");if(!(bool)reply["ok"]){if(reply["result"].Type!=JTokenType.Null||reply["error"].Type!=JTokenType.String||((string)reply["error"]).Length>2048)throw new InvalidDataException("content-surface-reply-error");throw new InvalidOperationException("content-surface:"+(string)reply["error"]);}if(!(reply["result"] is JObject result)||reply["error"].Type!=JTokenType.Null)throw new InvalidDataException("content-surface-reply-result");return result;}}).ConfigureAwait(false);}finally{lane.Release();}}
  public async Task<RuntimePackageInspection> InspectPackageAsync(string path){var result=await CallAsync("Inspect",new JObject{{"package",path}}).ConfigureAwait(false);TrustedRuntimeDistribution.Fields(result,"build","archive_sha256","capabilities");var tags=result["capabilities"] as JArray;if(tags==null||tags.Count>32||tags.Any(t=>t.Type!=JTokenType.String||!CapabilityNames.Contains((string)t)))throw new InvalidDataException("content-surface-inspection-capabilities");return new RuntimePackageInspection(TrustedRuntimeDistribution.Text(result["build"]),TrustedRuntimeDistribution.Text(result["archive_sha256"]),tags.Select(t=>(string)t).ToArray());}
  public void Dispose(){lane.Wait();try{if(disposed)return;disposed=true;owner.Dispose();}finally{lane.Release();}}
 }
}
